// Included after platform input/render helpers; all layout coordinates are Vita pixels.
static const Weather& viewWeather(){return weatherRegion>=0&&weatherRegion<(int)state.regions.size()?state.regions[weatherRegion].weather:state.weather;}
static const Location& viewLocation(){return weatherRegion>=0&&weatherRegion<(int)state.regions.size()?state.regions[weatherRegion].location:state.location;}
static Date forecastToday(){auto l=viewLocation();auto n=clockAt(zoneOffset(zoneRules(),l.zone,utcNow(),l.offset));return {n.year,n.month,n.day};}
static std::string numeric(double n,int decimals=0){if(!std::isfinite(n))return "—";char s[48];snprintf(s,sizeof(s),"%.*f",std::clamp(decimals,0,2),n);return s;}
static std::string temp(double c,bool unit=false){return numeric(temperature(c,state.units))+ (unit?(state.units?"°F":"°C"):"°");}
static std::string wind(double kmh){return numeric(windSpeed(kmh,state.units))+t(state.units?" mph":" км/ч",state.units?" mph":" km/h");}
static std::string rainIn(double mm,int units){double v=precipitation(mm,units);if(units&&v>0&&v<0.01)return "<0.01 in";return numeric(v,units?2:1)+(units?" in":t(" мм"," mm"));}
static std::string rain(double mm){return rainIn(mm,state.units);}
[[maybe_unused]] static std::string weatherLabel(int c){if(!state.language)return weatherName(c);if(c==0)return "Clear";if(c<=3)return "Cloudy";if(c==45||c==48)return "Fog";if(c>=51&&c<=67)return "Rain";if(c>=71&&c<=77)return "Snow";if(c>=80&&c<=82)return "Showers";if(c==85||c==86)return "Snow showers";if(c>=95)return "Thunderstorm";return "Weather";}
static const Json& daily(){static const Json empty=Json::object();auto it=viewWeather().details.find("daily");return it!=viewWeather().details.end()&&it->is_object()?*it:empty;}
static const Json& hourly(){static const Json empty=Json::object();auto it=viewWeather().details.find("hourly");return it!=viewWeather().details.end()&&it->is_object()?*it:empty;}
static std::string stringAt(const Json& j,const char* field,int index){auto it=j.find(field);return it!=j.end()&&it->is_array()&&index>=0&&index<(int)it->size()&&(*it)[index].is_string()?(*it)[index].get<std::string>():"";}
static std::vector<int> hoursForDay(int d){std::vector<int> out;if(d<0||d>=(int)viewWeather().dates.size())return out;auto it=hourly().find("time");if(it==hourly().end()||!it->is_array())return out;for(size_t i=0;i<it->size()&&i<300;++i){std::string stamp=(*it)[i];if(stamp.substr(0,10)==viewWeather().dates[d])out.push_back(i);}if(!out.empty()){int next=out.back()+1;if(next<(int)it->size()&&(*it)[next].get<std::string>().substr(11,5)=="00:00")out.push_back(next);}return out;}
static std::string stampTime(const std::string& stamp){if(stamp.size()<16)return "—";int h=atoi(stamp.substr(11,2).c_str()),m=atoi(stamp.substr(14,2).c_str());return clockTime(h,m,state.time24);}
static std::string holidayTitle(const Holiday& h){return h.country=="USR"?h.name:localizedHolidayTitle(h,state.language);}
static std::vector<Country> catalog(){if(!state.catalog.empty())return state.catalog;return {{"US","United States",1},{"GB","United Kingdom",2},{"DE","Germany",3},{"FR","France",4},{"IT","Italy",5},{"ES","Spain",6},{"CA","Canada",7},{"AU","Australia",8},{"JP","Japan",1},{"RU","Russia",2},{"UA","Ukraine",3},{"PL","Poland",4},{"NL","Netherlands",5},{"BE","Belgium",6},{"PT","Portugal",7},{"BR","Brazil",8},{"MX","Mexico",1},{"AT","Austria",2},{"CH","Switzerland",3},{"SE","Sweden",4},{"NO","Norway",5},{"FI","Finland",6},{"DK","Denmark",7},{"CZ","Czechia",8}};}
static std::string countryName(const Country& c){if(state.language)return englishCountries.value(c.code,c.name);static const std::map<std::string,std::string> names={{"US","США"},{"GB","Великобритания"},{"DE","Германия"},{"FR","Франция"},{"IT","Италия"},{"ES","Испания"},{"CA","Канада"},{"AU","Австралия"},{"JP","Япония"},{"RU","Россия"},{"UA","Украина"},{"PL","Польша"},{"NL","Нидерланды"},{"BE","Бельгия"},{"PT","Португалия"},{"BR","Бразилия"},{"MX","Мексика"},{"AT","Австрия"},{"CH","Швейцария"},{"SE","Швеция"},{"NO","Норвегия"},{"FI","Финляндия"},{"DK","Дания"},{"CZ","Чехия"}};auto it=names.find(c.code);return it!=names.end()?it->second:localizedCountries.value(c.code,c.name);}
