static void weatherIcon(int x,int y,int code,int radius=9){int kind=code==0?9:code<=2?10:code==3?5:code==45||code==48?13:(code>=71&&code<=77)||code==85||code==86?12:code>=95?14:11;unsigned color=kind==9||kind==10?RGBA8(244,169,61,255):kind==11?RGBA8(55,154,238,255):kind==12?RGBA8(70,181,216,255):kind==14?RGBA8(221,137,232,255):p.muted;drawAssetIcon(x,y,kind,radius<=6?24:32,color);}
