static void outline(int x,int y,int w,int h,unsigned c,int thickness=2){rect(x,y,w,thickness,c);rect(x,y+h-thickness,w,thickness,c);rect(x,y,thickness,h,c);rect(x+w-thickness,y,thickness,h,c);}
static void card(int x,int y,int w,int h){for(int row=0;row<h;++row){int edge=std::min(row,h-1-row);int inset=edge>=8?0:(int)std::ceil(8-std::sqrt(64.f-(8-edge-0.5f)*(8-edge-0.5f)));rect(x+inset,y+row,w-inset*2,1,p.card);}}
static std::string valueIn(double n,int metric,int units){return metric==0?numeric(temperature(n,units))+ (units?"°F":"°C"):metric==1?rainIn(n,units):metric==3?numeric(windSpeed(n,units))+(units?" mph":t(" км/ч"," km/h")):metric==4?(units?numeric(n/33.8638866667,2)+" inHg":numeric(n)+" hPa"):numeric(n)+"%";}
