    if(vertical){weatherIcon(x+width/2,y+16,state.weather.code,9);std::string primary=temp(state.weather.temperature,true);int size=22;while(size>16&&textWidth(size,primary)>width) --size;fit(x+std::max(0,(width-textWidth(size,primary))/2),y+51,size,primary,width,metricColor(0));if(state.dualUnits){auto secondary=valueIn(state.weather.temperature,0,1-state.units);fit(x+std::max(0,(width-textWidth(12,secondary))/2),y+69,12,secondary,width,p.muted);}}
